  "measure_id": "SYN-0001",
  "restatements": [
    {
      "clause_id": "SYN-0001 §1",
      "text": "Requires individuals who keep firearms in a residence to store them in a locked container when not being carried or used."
    },
    {
      "clause_id": "SYN-0001 §2",
      "text": "Requires the Department to issue storage certificates to applicants who pay a $25 fee."
    },
    {
      "clause_id": "SYN-0001 §3",
      "text": "Preempts local governments from adopting or enforcing firearm storage ordinances, making the state the sole authority on the matter."
    }
  ],
